$ErrorActionPreference='Stop'; $base=Join-Path $PSScriptRoot '..'; $runs=Join-Path $base 'runs'; $out=Join-Path $base 'outputs'; $probe=Get-Content -Raw (Join-Path $runs 'feature_probe_manifest.json')|ConvertFrom-Json; $p4=$probe|Where-Object k -eq 4|Select-Object -First 1; $p32=$probe|Where-Object k -eq 32|Select-Object -First 1; $a=@(Import-Csv (Join-Path (Join-Path $runs $p4.run) 'model_features.csv')); $b=@(Import-Csv (Join-Path (Join-Path $runs $p32.run) 'model_features.csv'))
$rawCols=@(0..31|ForEach-Object{'raw_f{0:d2}'-f $_});$normCols=@(0..31|ForEach-Object{'normalized_f{0:d2}'-f $_});$rawRows=0;$rawCells=0;$normRows=0;$normCells=0;$predChanges=0;$maxRaw=0.0;$maxNorm=0.0;$maxPred=0.0;$align=0
for($i=0;$i -lt $a.Count;$i++){if($a[$i].edge_id -ne $b[$i].edge_id -or $a[$i].source -ne $b[$i].source -or $a[$i].target -ne $b[$i].target){$align++;continue};$rc=0;$nc=0;foreach($c in $rawCols){$d=[Math]::Abs([double]::Parse($a[$i].$c,[Globalization.CultureInfo]::InvariantCulture)-[double]::Parse($b[$i].$c,[Globalization.CultureInfo]::InvariantCulture));if($d -gt 0){$rc++;$rawCells++};if($d -gt $maxRaw){$maxRaw=$d}};foreach($c in $normCols){$d=[Math]::Abs([double]::Parse($a[$i].$c,[Globalization.CultureInfo]::InvariantCulture)-[double]::Parse($b[$i].$c,[Globalization.CultureInfo]::InvariantCulture));if($d -gt 0){$nc++;$normCells++};if($d -gt $maxNorm){$maxNorm=$d}};if($rc -gt 0){$rawRows++};if($nc -gt 0){$normRows++};$d=[Math]::Abs([double]::Parse($a[$i].prediction,[Globalization.CultureInfo]::InvariantCulture)-[double]::Parse($b[$i].prediction,[Globalization.CultureInfo]::InvariantCulture));if($d -gt 0){$predChanges++};if($d -gt $maxPred){$maxPred=$d}}
$direction=[System.Collections.Generic.List[object]]::new();foreach($rows in @(@{k=4;data=$a},@{k=32;data=$b})){ $map=@{};foreach($row in $rows.data){$map["$($row.source):$($row.target)"]=$row};$missing=0;$pairs=0;$rawMismatch=0;$scoreMax=0.0;foreach($row in $rows.data){if([int]$row.source -lt [int]$row.target){$rev=$map["$($row.target):$($row.source)"];if($null -eq $rev){$missing++}else{$pairs++;foreach($c in $rawCols){if([double]::Parse($row.$c,[Globalization.CultureInfo]::InvariantCulture) -ne [double]::Parse($rev.$c,[Globalization.CultureInfo]::InvariantCulture)){$rawMismatch++;break}};$d=[Math]::Abs([double]::Parse($row.prediction,[Globalization.CultureInfo]::InvariantCulture)-[double]::Parse($rev.prediction,[Globalization.CultureInfo]::InvariantCulture));if($d -gt $scoreMax){$scoreMax=$d}}}};$direction.Add([pscustomobject]@{k=$rows.k;directed_arcs=$rows.data.Count;undirected_pairs=$pairs;reverse_missing=$missing;reverse_raw_vector_mismatch_pairs=$rawMismatch;reverse_max_prediction_delta=$scoreMax}) }
$cmp=[pscustomobject]@{graph='er1024_p001_seed20260930';seed=0;k_low=4;k_high=32;diagnostic_common_config='--preset-type=default --c-t=20 --t=1 --seed=0; extra c-t is only to make learned coarsener invoke the model at both k';aligned_edge_rows=$a.Count;alignment_errors=$align;raw_feature_rows_changed=$rawRows;raw_feature_cells_changed=$rawCells;raw_feature_cells_total=($a.Count*32);max_abs_raw_feature_delta=$maxRaw;normalized_feature_rows_changed=$normRows;normalized_feature_cells_changed=$normCells;max_abs_normalized_feature_delta=$maxNorm;predictions_changed=$predChanges;max_abs_prediction_delta=$maxPred;direction_checks=$direction}
$cmp|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $out 'k_feature_probe.json') -Encoding utf8
$defaults=[System.Collections.Generic.List[object]]::new();$manifest=Get-Content -Raw (Join-Path $runs 'run_manifest.json')|ConvertFrom-Json;foreach($grp in ($manifest|Where-Object method -eq 'learned'|Group-Object graph,seed)){ $items=@($grp.Group|Sort-Object k);$low=$items|Where-Object k -eq 4|Select-Object -First 1;$high=$items|Where-Object k -eq 32|Select-Object -First 1;$lim4=[regex]::Match((Get-Content -Raw (Join-Path (Join-Path $runs $low.run) 'stdout.log')),'Contraction Limit:\s+(\d+)').Groups[1].Value;$lim32=[regex]::Match((Get-Content -Raw (Join-Path (Join-Path $runs $high.run) 'stdout.log')),'Contraction Limit:\s+(\d+)').Groups[1].Value;$defaults.Add([pscustomobject]@{graph=$low.graph;seed=$low.seed;k4_default_model_invoked=(Test-Path (Join-Path (Join-Path $runs $low.run) 'model_features.csv'));k32_default_model_invoked=(Test-Path (Join-Path (Join-Path $runs $high.run) 'model_features.csv'));k4_contraction_limit=[int]$lim4;k32_contraction_limit=[int]$lim32;input_nodes=1024;explanation='Default guided coarsening asks for t*k nodes (t=160). At k=32 the 5120-node stopping target exceeds this input size, so the default run does not call the learned scorer.'}) };$defaults|Export-Csv -NoTypeInformation -Encoding utf8 -LiteralPath (Join-Path $out 'default_model_invocation.csv')
$cmp|ConvertTo-Json -Depth 5; $defaults|Format-Table graph,seed,k4_default_model_invoked,k32_default_model_invoked,k4_contraction_limit,k32_contraction_limit -AutoSize
